practice.solution:
def mean_pool(vectors, mask):
    dim = len(vectors[0])
    acc = [0.0] * dim
    n = 0
    for v, m in zip(vectors, mask):
        if m == 1:
            n = n + 1
            for j in range(dim):
                acc[j] = acc[j] + v[j]
    return [round(a / n, 3) for a in acc]

