import math
def fill_schema(heads, hidden):
    out = []
    for name, kind, w in heads:
        z = sum([w[i] * hidden[i] for i in range(len(hidden))])
        if kind == 'boolean':
            out.append([name, round(1 / (1 + math.exp(-z)), 3)])
        else:
            out.append([name, round(z, 3)])
    return out

