def best_threshold(conf, correct, candidates, c_wrong, c_review):
    best = None
    bc = None
    for t in candidates:
        cost = 0
        for c, ok in zip(conf, correct):
            if c >= t:
                if not ok:
                    cost = cost + c_wrong
            else:
                cost = cost + c_review
        if bc is None or cost < bc:
            bc = cost
            best = t
    return best

